// Sentence-building exercises (generated by `npm run sentences`). The exercises are static files in
// public/sentences, fetched per level, so they stay out of the page bundle and the Worker.
import {z} from 'zod';
import data from './generated/sentences.json';
import type {Level} from './catalog';
import {localizedText} from './schemas';

const exerciseSchema = z.object({
  id: z.string().min(1), japanese: z.string().min(1), ruby: z.string().optional(), end: z.string(),
  translations: localizedText,
  chunks: z.array(z.object({text: z.string().min(1), ruby: z.string().optional()})).min(2)
});
export type SentenceExercise = z.infer<typeof exerciseSchema>;

const levels = data.levels as Record<Level, {count: number; version: string}>;
export function sentenceCount(level: Level): number {return levels[level].count;}

const cache = new Map<Level, Promise<SentenceExercise[]>>();
export function loadSentences(level: Level): Promise<SentenceExercise[]> {
  let pending = cache.get(level);
  if (!pending) {
    pending = fetch(`/sentences/${level.toLowerCase()}.json?v=${levels[level].version}`).then(async response => {
      if (!response.ok) throw new Error(`Sentences ${level}: ${response.status}`);
      const parsed = z.array(exerciseSchema).safeParse(await response.json());
      if (!parsed.success) throw new Error(`Sentences ${level}: bad format`);
      return parsed.data;
    });
    pending.catch(() => cache.delete(level));
    cache.set(level, pending);
  }
  return pending;
}

/** A built answer is right when its chunks spell the model sentence (so identical chunks may swap). */
export function isSentenceCorrect(exercise: SentenceExercise, order: number[]): boolean {
  return order.length === exercise.chunks.length && order.map(i => exercise.chunks[i].text).join('') === exercise.chunks.map(c => c.text).join('');
}

/** A shuffled order of chunk indexes that never reads as the model sentence. */
export function shuffledChunks(exercise: SentenceExercise, random = Math.random): number[] {
  const order = exercise.chunks.map((_, i) => i);
  for (let attempt = 0; attempt < 20; attempt++) {
    for (let i = order.length - 1; i > 0; i--) {
      const j = Math.floor(random() * (i + 1));
      [order[i], order[j]] = [order[j], order[i]];
    }
    if (!isSentenceCorrect(exercise, order)) return order;
  }
  return order.slice(1).concat(order[0]); // Rotating always changes the text when chunks differ.
}
